def _pct(x: float, digits: int = 1) -> str:
    return f"{100 * x:.{digits}f}"


def _table(header: list[str], rows: list[list[str]]) -> list[str]:
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(r) + " |" for r in rows]
    return out


def _write_csv(path: Path, rows: list[dict]):
    with open(path, "w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=list(rows[0]))
        writer.writeheader()
        for r in rows:
            writer.writerow({k: f"{v:.6f}" if isinstance(v, float) else v for k, v in r.items()})


def write_outputs(out_dir: Path, ctx: dict):
    out_dir.mkdir(parents=True, exist_ok=True)
    layouts, metrics, scores = ctx["layouts"], ctx["metrics"], ctx["scores"]

    _write_csv(out_dir / "scores.csv", [
        {"layout": lay.id, "score": scores[lay.id], **metrics[lay.id]} for lay in layouts])
    _write_csv(out_dir / "finger_load.csv", [
        {"layout": lay.id, "finger": f, "finger_name": FINGER_NAMES[f], "share": metrics[lay.id][f"finger_{f}"]}
        for lay in layouts for f in FINGERS])
    _write_csv(out_dir / "worst_same_finger_bigrams.csv", [
        {"layout": lay.id, **row} for lay in layouts for row in ctx["worst_sfb"][lay.id]])
    _write_csv(out_dir / "top_ngrams.csv", [
        {"n": n, "ngram": g, "count": c, "share": share}
        for n, items in ctx["ngrams"].items() for g, c, share in items])
    _write_csv(out_dir / "sensitivity.csv", ctx["sensitivity"])

    for lang in ("en", "it"):
        name = "layout_comparison_report.md" if lang == "en" else "layout_comparison_report.it.md"
        (out_dir / name).write_text(render_report(ctx, lang), encoding="utf-8")


def render_report(ctx: dict, lang: str) -> str:
    t = TEXT[lang]
    layouts, metrics, scores = ctx["layouts"], ctx["metrics"], ctx["scores"]
    corpus = ctx["corpus"]
    ranked = sorted(layouts, key=lambda lay: scores[lay.id])
    lines = [f"# {t['title']}", "", t["other"], "", f"_{t['generated']}_", ""]

    lines += [f"## {t['corpus']}", "", t["corpus_line"].format(
        source=ctx["corpus_path"], words=len(corpus.words), tokens=corpus.tokens, chars=corpus.characters)]
    if ctx["letters_only"]:
        lines += ["", t["letters_note"]]
    lines += [""]

    lines += [f"## {t['weights']}", "", t["weights_note"], ""]
    lines += _table(["metric", "weight"], [[f"`{k}`", f"{v:+.2f}"] for k, v in ctx["weights"].items()])
    lines += [""]

    lines += [f"## {t['layouts']}", ""]
    for lay in layouts:
        top, home, bottom = lay.letter_rows()
        lines += [f"**{lay.name}** (`{lay.id}`): {lay.description}", "", "```",
                  f"{' '.join(top[:5])}   {' '.join(top[5:])}",
                  f"{' '.join(home[:5])}   {' '.join(home[5:])}",
                  f"{' '.join(bottom[:5])}   {' '.join(bottom[5:])}", "```", ""]

    lines += [f"## {t['scores']}", "", t["scores_note"], ""]
    header = [t[k] for k in ("rank", "layout", "score", "home", "top", "bottom", "dist", "sfb",
                             "alt", "inward", "outward", "pinky", "left", "accent")]
    rows = []
    for i, lay in enumerate(ranked, 1):
        m = metrics[lay.id]
        rows.append([str(i), lay.id, f"{scores[lay.id]:.4f}", _pct(m["home_row"]), _pct(m["top_row"]),
                     _pct(m["bottom_row"]), f"{m['mean_distance']:.3f}", _pct(m["same_finger_bigrams"], 2),
                     _pct(m["hand_alternation"]), _pct(m["roll_inward"]), _pct(m["roll_outward"]),
                     _pct(m["pinky_load"]), _pct(m["left_hand"]), _pct(m["accent_extra_keystrokes"], 2)])
    lines += _table(header, rows) + [""]

    s = ctx["sensitivity_params"]
    lines += [f"## {t['sensitivity']}", "", t["sens_note"].format(
        samples=s["samples"], lo=1 - s["spread"], hi=1 + s["spread"]), ""]
    lines += _table([t["layout"], t["mean_rank"], t["first"], t["range"]], [
        [r["layout"], f"{r['mean_rank']:.2f}", _pct(r["first_share"]) + "%", f"{r['best_rank']}–{r['worst_rank']}"]
        for r in ctx["sensitivity"]]) + [""]

    lines += [f"## {t['fingers']}", ""]
    lines += _table([t["layout"]] + FINGERS, [
        [lay.id] + [_pct(metrics[lay.id][f"finger_{f}"]) for f in FINGERS] for lay in layouts]) + [""]

    focus = next((lay for lay in layouts if lay.id == ctx["focus"]), ranked[0])
    lines += [f"## {t['worst'].format(name=focus.name)}", "", t["worst_note"], ""]
    lines += _table([t["bigram"], t["finger"], t["share"], t["keydist"]], [
        [f"`{r['bigram'].replace('DK', '◌')}`", r["finger"], _pct(r["share"], 2) + "%", f"{r['key_distance']:.2f}"]
        for r in ctx["worst_sfb"][focus.id][:10]]) + [""]

    lines += [f"## {t['ngrams']}", ""]
    for n, key in ((1, "letters"), (2, "bigrams"), (3, "trigrams")):
        items = ctx["ngrams"][n][:20]
        lines += [f"**{t[key]}:** " + ", ".join(f"`{g}` {_pct(share, 2)}%" for g, _, share in items), ""]

    lines += [f"## {t['limits']}", ""] + [f"- {x}" for x in t["limits_body"]] + [""]
    return "\n".join(lines)
